# Hindi / Gujarati text for Political Science Ch 4 lesson, sections 4-6.
TEXT_B = {
 "s4.thm.title": ("भारत के मान्यता प्राप्त दल", "ભારતના માન્યતા પ્રાપ્ત પક્ષો"),
 "s4.thm.body": (
  "दुनिया भर में संघीय व्यवस्था वाले लोकतंत्रों में दो तरह के दल होते हैं: संघ की किसी एक इकाई में मौजूद दल, और संघ की कई या सभी इकाइयों में मौजूद दल। भारत भी इसका अपवाद नहीं है।\n\n"
  "**चुनाव आयोग द्वारा मान्यता:** देश के हर दल को चुनाव आयोग में अपना **पंजीकरण** कराना पड़ता है। आयोग सभी दलों को समान मानता है, पर बड़े और स्थापित दलों को कुछ विशेष सुविधाएँ देता है। इन दलों को एक **अलग चुनाव चिह्न** दिया जाता है: केवल उस दल के अधिकृत उम्मीदवार ही उस चिह्न का इस्तेमाल कर सकते हैं। यह विशेषाधिकार और कुछ अन्य सुविधाएँ पाने वाले दल चुनाव आयोग से **'मान्यता प्राप्त'** होते हैं।\n"
  "- **राज्यस्तरीय (प्रांतीय) दल:** जो दल किसी राज्य के **विधानसभा** चुनाव में पड़े कुल मतों का कम से कम **6 प्रतिशत** पाता है और कम से कम **दो सीटें** जीतता है।\n"
  "- **राष्ट्रीय दल:** जो दल **लोकसभा** चुनाव में या **चार राज्यों** के विधानसभा चुनावों में पड़े कुल मतों का कम से कम **6 प्रतिशत** पाता है, और लोकसभा में कम से कम **चार सीटें** जीतता है।\n\n"
  "**राष्ट्रीय दल (2023 से चुनाव आयोग की मान्यता के अनुसार):** NCERT पुस्तक में छपने के समय मान्यता प्राप्त दलों की सूची है; 2023 में आयोग की सूची में **छह** राष्ट्रीय दल थे:\n"
  "- **भारतीय राष्ट्रीय कांग्रेस (INC):** **1885** में गठित; कई बार विभाजित हुई। आज़ादी के बाद कई दशकों तक भारतीय राजनीति में इसकी प्रमुख भूमिका रही। विचारधारा में **मध्यमार्गी** दल, यह **धर्मनिरपेक्षता** और **कमज़ोर वर्गों तथा अल्पसंख्यकों के कल्याण** का समर्थन करती है। इसने **2004 से 2014** तक **संयुक्त प्रगतिशील गठबंधन (यूपीए)** सरकार का नेतृत्व किया।\n"
  "- **भारतीय जनता पार्टी (BJP):** **1951** में **श्यामा प्रसाद मुखर्जी** द्वारा गठित **भारतीय जनसंघ** को पुनर्जीवित करके **1980** में बनी। यह भारत की प्राचीन संस्कृति और मूल्यों से प्रेरणा लेकर मज़बूत और आधुनिक भारत बनाना चाहती है; **सांस्कृतिक राष्ट्रवाद (हिंदुत्व)** भारतीय राष्ट्रीयता की इसकी अवधारणा का एक अहम तत्व है, और दीनदयाल उपाध्याय का **'एकात्म मानववाद'** इसका मार्गदर्शक दर्शन है। यह **राष्ट्रीय जनतांत्रिक गठबंधन (एनडीए)** का नेतृत्व करती है और **2014, 2019 और 2024** के चुनावों के बाद केंद्र में सरकार बनाई।\n"
  "- **बहुजन समाज पार्टी (BSP):** **कांशीराम** के नेतृत्व में **1984** में गठित। यह **बहुजन समाज**, जिसमें **दलित, आदिवासी, पिछड़ी जातियाँ और धार्मिक अल्पसंख्यक** शामिल हैं, का प्रतिनिधित्व करने और उनके लिए सत्ता पाने का प्रयास करती है। यह **साहू महाराज, महात्मा फुले, पेरियार रामास्वामी नायकर और बाबासाहब आंबेडकर** के विचारों और शिक्षाओं से प्रेरणा लेती है। इसका मुख्य आधार **उत्तर प्रदेश** में है।\n"
  "- **भारतीय कम्युनिस्ट पार्टी (मार्क्सवादी) (CPI-M):** **1964** में गठित। यह **मार्क्सवाद-लेनिनवाद** में आस्था रखती है, **समाजवाद, धर्मनिरपेक्षता और लोकतंत्र** का समर्थन करती है, और **साम्राज्यवाद तथा सांप्रदायिकता** का विरोध करती है। **पश्चिम बंगाल, केरल और त्रिपुरा** में इसका मज़बूत आधार है।\n"
  "- **आम आदमी पार्टी (AAP):** **2012** में गठित; **2023** में राष्ट्रीय दल की मान्यता मिली।\n"
  "- **नेशनल पीपुल्स पार्टी (NPP):** **2013** में **पी.ए. संगमा** द्वारा गठित; **2019** में राष्ट्रीय दल की मान्यता मिली, यह दर्जा पाने वाला **पूर्वोत्तर** का पहला दल।\n\n"
  "**राज्यस्तरीय दल:** इनके अलावा अधिकतर बड़े दल **'राज्यस्तरीय दल'** की श्रेणी में आते हैं, जिन्हें आमतौर पर क्षेत्रीय दल कहा जाता है। इनमें से कुछ अखिल भारतीय दल हैं जो कुछ ही राज्यों में सफल हो पाए। **बीजू जनता दल, सिक्किम डेमोक्रेटिक फ़्रंट, मिज़ो नेशनल फ़्रंट** और **तेलुगु देशम पार्टी** जैसे दल अपनी राज्यीय पहचान को लेकर सचेत हैं।\n"
  "- पिछले तीन दशकों में इन दलों की संख्या और ताक़त बढ़ी है। इससे **भारत की संसद राजनीतिक रूप से अधिक विविधतापूर्ण** हुई है।\n"
  "- **1989 से 2014** तक कोई भी राष्ट्रीय दल अपने दम पर लोकसभा में बहुमत नहीं पा सका। नतीजतन राष्ट्रीय दलों को राज्यस्तरीय दलों से गठबंधन करना पड़ा। 1996 के बाद से लगभग हर राज्यस्तरीय दल को किसी न किसी **राष्ट्रीय गठबंधन सरकार** का हिस्सा बनने का अवसर मिला है। इससे हमारे देश में **संघवाद और लोकतंत्र मज़बूत** हुए हैं।",
  "દુનિયાભરમાં સમવાયી વ્યવસ્થાવાળી લોકશાહીમાં બે પ્રકારના પક્ષો હોય છે: સમવાયના એક જ એકમમાં હાજર પક્ષો, અને અનેક કે બધાં એકમોમાં હાજર પક્ષો. ભારત પણ તેમાં અપવાદ નથી.\n\n"
  "**ચૂંટણી પંચ દ્વારા માન્યતા:** દેશના દરેક પક્ષે ચૂંટણી પંચમાં **નોંધણી** કરાવવી પડે છે. પંચ બધા પક્ષોને સમાન ગણે છે, પણ મોટા અને સ્થાપિત પક્ષોને કેટલીક ખાસ સુવિધાઓ આપે છે. આ પક્ષોને **અલગ ચૂંટણી પ્રતીક** અપાય છે: ફક્ત તે પક્ષના સત્તાવાર ઉમેદવારો જ તે પ્રતીક વાપરી શકે. આ વિશેષાધિકાર અને બીજી સુવિધાઓ મેળવનારા પક્ષો ચૂંટણી પંચ દ્વારા **'માન્યતા પ્રાપ્ત'** હોય છે.\n"
  "- **રાજ્ય કક્ષાનો પક્ષ:** જે પક્ષ કોઈ રાજ્યની **વિધાનસભા** ચૂંટણીમાં કુલ મતોના ઓછામાં ઓછા **6 ટકા** મેળવે અને ઓછામાં ઓછી **બે બેઠકો** જીતે.\n"
  "- **રાષ્ટ્રીય પક્ષ:** જે પક્ષ **લોકસભા** ચૂંટણીમાં કે **ચાર રાજ્યોની** વિધાનસભા ચૂંટણીમાં કુલ મતોના ઓછામાં ઓછા **6 ટકા** મેળવે, અને લોકસભામાં ઓછામાં ઓછી **ચાર બેઠકો** જીતે.\n\n"
  "**રાષ્ટ્રીય પક્ષો (2023થી ચૂંટણી પંચની માન્યતા મુજબ):** NCERT પુસ્તકમાં છપાતી વખતની યાદી છે; 2023માં પંચની યાદીમાં **છ** રાષ્ટ્રીય પક્ષો હતા:\n"
  "- **ભારતીય રાષ્ટ્રીય કૉંગ્રેસ (INC):** **1885**માં સ્થપાઈ; ઘણી વાર વિભાજિત થઈ. આઝાદી પછી ઘણા દાયકા સુધી ભારતીય રાજકારણમાં તેની પ્રભાવી ભૂમિકા રહી. વિચારધારામાં **મધ્યમમાર્ગી** પક્ષ, તે **બિનસાંપ્રદાયિકતા** અને **નબળા વર્ગો તથા લઘુમતીઓના કલ્યાણ**નું સમર્થન કરે છે. તેણે **2004થી 2014** સુધી **સંયુક્ત પ્રગતિશીલ ગઠબંધન (UPA)** સરકારનું નેતૃત્વ કર્યું.\n"
  "- **ભારતીય જનતા પાર્ટી (BJP):** **1951**માં **શ્યામાપ્રસાદ મુખર્જી**એ રચેલા **ભારતીય જનસંઘ**ને પુનર્જીવિત કરી **1980**માં રચાઈ. તે ભારતની પ્રાચીન સંસ્કૃતિ અને મૂલ્યોમાંથી પ્રેરણા લઈ મજબૂત અને આધુનિક ભારત બનાવવા માગે છે; **સાંસ્કૃતિક રાષ્ટ્રવાદ (હિંદુત્વ)** તેની ભારતીય રાષ્ટ્રીયતાની વિભાવનાનું મહત્ત્વનું તત્ત્વ છે, અને દીનદયાળ ઉપાધ્યાયનો **'એકાત્મ માનવવાદ'** તેનું માર્ગદર્શક દર્શન છે. તે **રાષ્ટ્રીય લોકતાંત્રિક ગઠબંધન (NDA)**નું નેતૃત્વ કરે છે અને **2014, 2019 અને 2024**ની ચૂંટણી પછી કેન્દ્રમાં સરકાર રચી.\n"
  "- **બહુજન સમાજ પાર્ટી (BSP):** **કાંશીરામ**ના નેતૃત્વમાં **1984**માં રચાઈ. તે **બહુજન સમાજ**, જેમાં **દલિતો, આદિવાસીઓ, અન્ય પછાત વર્ગો અને ધાર્મિક લઘુમતીઓ** સામેલ છે, તેનું પ્રતિનિધિત્વ કરવા અને તેમના માટે સત્તા મેળવવા પ્રયત્ન કરે છે. તે **શાહૂ મહારાજ, મહાત્મા ફુલે, પેરિયાર રામાસ્વામી નાયકર અને બાબાસાહેબ આંબેડકર**ના વિચારો અને શિક્ષણમાંથી પ્રેરણા લે છે. તેનો મુખ્ય આધાર **ઉત્તર પ્રદેશ**માં છે.\n"
  "- **ભારતીય સામ્યવાદી પક્ષ (માર્ક્સવાદી) (CPI-M):** **1964**માં સ્થપાયો. તે **માર્ક્સવાદ-લેનિનવાદ**માં માને છે, **સમાજવાદ, બિનસાંપ્રદાયિકતા અને લોકશાહી**નું સમર્થન કરે છે, અને **સામ્રાજ્યવાદ તથા કોમવાદ**નો વિરોધ કરે છે. **પશ્ચિમ બંગાળ, કેરળ અને ત્રિપુરા**માં તેનો મજબૂત આધાર છે.\n"
  "- **આમ આદમી પાર્ટી (AAP):** **2012**માં સ્થપાઈ; **2023**માં રાષ્ટ્રીય પક્ષની માન્યતા મળી.\n"
  "- **નૅશનલ પીપલ્સ પાર્ટી (NPP):** **2013**માં **પી.એ. સંગમા**એ સ્થાપી; **2019**માં રાષ્ટ્રીય પક્ષની માન્યતા મળી, આ દરજ્જો મેળવનાર **ઈશાન ભારત**નો પહેલો પક્ષ.\n\n"
  "**રાજ્ય કક્ષાના પક્ષો:** આ ઉપરાંત મોટા ભાગના મોટા પક્ષો **'રાજ્ય કક્ષાના પક્ષો'**ની શ્રેણીમાં આવે છે, જેને સામાન્ય રીતે પ્રાદેશિક પક્ષો કહે છે. તેમાંથી કેટલાક અખિલ ભારતીય પક્ષો છે જે થોડાં જ રાજ્યોમાં સફળ થયા. **બીજુ જનતા દળ, સિક્કિમ ડેમોક્રેટિક ફ્રન્ટ, મિઝો નૅશનલ ફ્રન્ટ** અને **તેલુગુ દેશમ પાર્ટી** જેવા પક્ષો પોતાની રાજ્ય ઓળખ પ્રત્યે સભાન છે.\n"
  "- છેલ્લા ત્રણ દાયકામાં આ પક્ષોની સંખ્યા અને શક્તિ વધી છે. તેનાથી **ભારતની સંસદ રાજકીય રીતે વધુ વૈવિધ્યસભર** બની છે.\n"
  "- **1989થી 2014** સુધી કોઈ રાષ્ટ્રીય પક્ષ પોતાના જોરે લોકસભામાં બહુમતી મેળવી શક્યો નહિ. પરિણામે રાષ્ટ્રીય પક્ષોએ રાજ્ય કક્ષાના પક્ષો સાથે ગઠબંધન કરવું પડ્યું. 1996થી લગભગ દરેક રાજ્ય કક્ષાના પક્ષને કોઈ ને કોઈ **રાષ્ટ્રીય ગઠબંધન સરકાર**નો ભાગ બનવાની તક મળી છે. તેનાથી આપણા દેશમાં **સમવાયતંત્ર અને લોકશાહી મજબૂત** બન્યાં છે."),
 "s4.table.title": ("भारत के राष्ट्रीय दल", "ભારતના રાષ્ટ્રીય પક્ષો"),
 "s4.table.body": (
  "| राष्ट्रीय दल | स्थापना | मुख्य विचार |\n|---|---|---|\n| **भारतीय राष्ट्रीय कांग्रेस (INC)** | 1885 | मध्यमार्गी; धर्मनिरपेक्षता और कमज़ोर वर्गों तथा अल्पसंख्यकों का कल्याण; यूपीए का नेतृत्व (2004–2014) |\n"
  "| **भारतीय जनता पार्टी (BJP)** | 1980 (भारतीय जनसंघ, 1951 से) | सांस्कृतिक राष्ट्रवाद; 'एकात्म मानववाद'; एनडीए का नेतृत्व; 2014, 2019 और 2024 में सरकार बनाई |\n"
  "| **बहुजन समाज पार्टी (BSP)** | 1984 (कांशीराम) | बहुजन समाज के लिए सत्ता: दलित, आदिवासी, पिछड़ी जातियाँ और धार्मिक अल्पसंख्यक; साहू महाराज, फुले, पेरियार और आंबेडकर से प्रेरित; मुख्य आधार उत्तर प्रदेश |\n"
  "| **भारतीय कम्युनिस्ट पार्टी (मार्क्सवादी) (CPI-M)** | 1964 | मार्क्सवाद-लेनिनवाद; समाजवाद, धर्मनिरपेक्षता और लोकतंत्र; साम्राज्यवाद और सांप्रदायिकता का विरोध; केरल, पश्चिम बंगाल और त्रिपुरा में मज़बूत |\n"
  "| **आम आदमी पार्टी (AAP)** | 2012 | 2023 से राष्ट्रीय दल; भ्रष्टाचार-विरोध और सुशासन के मुद्दे |\n"
  "| **नेशनल पीपुल्स पार्टी (NPP)** | 2013 (पी.ए. संगमा) | 2019 से राष्ट्रीय दल; राष्ट्रीय दर्जा पाने वाला पूर्वोत्तर का पहला दल; मेघालय में आधार |",
  "| રાષ્ટ્રીય પક્ષ | સ્થાપના | મુખ્ય વિચારો |\n|---|---|---|\n| **ભારતીય રાષ્ટ્રીય કૉંગ્રેસ (INC)** | 1885 | મધ્યમમાર્ગી; બિનસાંપ્રદાયિકતા અને નબળા વર્ગો તથા લઘુમતીઓનું કલ્યાણ; UPAનું નેતૃત્વ (2004–2014) |\n"
  "| **ભારતીય જનતા પાર્ટી (BJP)** | 1980 (ભારતીય જનસંઘ, 1951માંથી) | સાંસ્કૃતિક રાષ્ટ્રવાદ; 'એકાત્મ માનવવાદ'; NDAનું નેતૃત્વ; 2014, 2019 અને 2024માં સરકાર રચી |\n"
  "| **બહુજન સમાજ પાર્ટી (BSP)** | 1984 (કાંશીરામ) | બહુજન સમાજ માટે સત્તા: દલિતો, આદિવાસીઓ, પછાત વર્ગો અને ધાર્મિક લઘુમતીઓ; શાહૂ મહારાજ, ફુલે, પેરિયાર અને આંબેડકરથી પ્રેરિત; મુખ્ય આધાર ઉત્તર પ્રદેશ |\n"
  "| **ભારતીય સામ્યવાદી પક્ષ (માર્ક્સવાદી) (CPI-M)** | 1964 | માર્ક્સવાદ-લેનિનવાદ; સમાજવાદ, બિનસાંપ્રદાયિકતા અને લોકશાહી; સામ્રાજ્યવાદ અને કોમવાદનો વિરોધ; કેરળ, પશ્ચિમ બંગાળ અને ત્રિપુરામાં મજબૂત |\n"
  "| **આમ આદમી પાર્ટી (AAP)** | 2012 | 2023થી રાષ્ટ્રીય પક્ષ; ભ્રષ્ટાચાર વિરોધ અને સુશાસનના મુદ્દા |\n"
  "| **નૅશનલ પીપલ્સ પાર્ટી (NPP)** | 2013 (પી.એ. સંગમા) | 2019થી રાષ્ટ્રીય પક્ષ; રાષ્ટ્રીય દરજ્જો મેળવનાર ઈશાન ભારતનો પહેલો પક્ષ; મેઘાલયમાં આધાર |"),
 "s5.thm.title": ("दलों में क्या ख़राबी है, और उन्हें कैसे सुधारा जाए?", "પક્ષોમાં શી ખામી છે, અને તેમને કેવી રીતે સુધારી શકાય?"),
 "s5.thm.body": (
  "दल लोकतंत्र का सबसे प्रकट रूप हैं, इसलिए लोकतंत्र के कामकाज में जो भी गड़बड़ी है, लोग उसके लिए दलों को दोषी ठहराते हैं। लोगों की नाराज़गी और आलोचना **चार समस्याओं** पर केंद्रित रही है:\n\n"
  "1. **पार्टी के भीतर आंतरिक लोकतंत्र का न होना:** दुनिया भर में दलों में सारी ताक़त **एक या कुछ नेताओं** के हाथ में सिमटने की प्रवृत्ति है। दल अपने **सदस्यों की सूची** नहीं रखते, **सांगठनिक बैठकें** नहीं करते, और **आंतरिक चुनाव** नियमित रूप से नहीं कराते। आम सदस्यों को दल के अंदर की जानकारी नहीं मिलती और फ़ैसलों को प्रभावित करने के साधन या संपर्क नहीं होते। नेता दल के नाम पर फ़ैसले लेने की ज़्यादा ताक़त हथिया लेते हैं। नेतृत्व से असहमत लोगों के लिए दल में टिके रहना मुश्किल हो जाता है। दल के सिद्धांतों और नीतियों से निष्ठा की जगह **नेता के प्रति निजी निष्ठा** ज़्यादा महत्त्वपूर्ण हो जाती है।\n"
  "2. **वंशवाद:** अधिकतर दल पारदर्शी तरीक़े से काम नहीं करते, इसलिए आम कार्यकर्ता के लिए शीर्ष तक पहुँचने के बहुत कम रास्ते होते हैं। जो नेता होते हैं, वे अनुचित लाभ लेकर अपने नज़दीकी लोगों या परिवार के सदस्यों को आगे बढ़ाते हैं। कई दलों में **शीर्ष पदों पर हमेशा एक ही परिवार के लोग** आते हैं। यह दल के दूसरे सदस्यों के साथ अन्याय है और लोकतंत्र के लिए अच्छा नहीं, क्योंकि पर्याप्त अनुभव या लोकप्रिय समर्थन के बिना लोग ताक़त वाले पदों पर पहुँच जाते हैं। यह प्रवृत्ति कुछ पुराने लोकतंत्रों समेत दुनिया भर में कुछ हद तक है।\n"
  "3. **पैसा और अपराधी तत्वों की बढ़ती घुसपैठ:** दलों का पूरा ध्यान चुनाव जीतने पर होता है, इसलिए वे छोटे रास्ते अपनाते हैं। वे ऐसे उम्मीदवार उतारते हैं जिनके पास **ख़ूब पैसा** हो या जो पैसा जुटा सकें। दलों को पैसा देने वाले अमीर लोग और कंपनियाँ उनकी नीतियों और फ़ैसलों को प्रभावित करते हैं। कुछ मामलों में दल चुनाव जीत सकने वाले **अपराधियों** का समर्थन करते हैं। दुनिया भर के लोकतंत्र समर्थक लोकतांत्रिक राजनीति में अमीर लोगों और बड़ी कंपनियों की बढ़ती भूमिका से चिंतित हैं।\n"
  "4. **सार्थक विकल्प का अभाव:** सार्थक विकल्प के लिए दलों में बड़ा अंतर होना चाहिए। हाल के वर्षों में दुनिया के अधिकतर हिस्सों में दलों के बीच **वैचारिक अंतर** कम हुआ है। हमारे देश में भी बड़े दलों के बीच आर्थिक मसलों पर अंतर घटा है। जो लोग सचमुच अलग नीतियाँ चाहते हैं, उनके पास कोई विकल्प नहीं है। कभी-कभी लोग बिल्कुल अलग नेता भी नहीं चुन पाते, क्योंकि वही नेता एक दल से दूसरे दल में आते-जाते रहते हैं।\n\n"
  "**दलों को सुधारने के लिए उठाए गए क़दम:**\n"
  "- **दल-बदल विरोधी क़ानून:** **दल-बदल** का अर्थ है जिस दल से चुने गए उसे छोड़कर दूसरे दल में चले जाना। कई विधायक और सांसद मंत्री बनने या पैसे के लालच में दल-बदल कर रहे थे। संविधान में संशोधन (**52वाँ संशोधन, 1985**) किया गया ताकि कोई विधायक या सांसद दल बदले तो उसकी विधायिका की **सीट चली जाएगी**। इससे दल-बदल कम हुआ, पर असहमति ज़ाहिर करना और कठिन हो गया: सांसदों और विधायकों को दल के नेताओं का हर फ़ैसला मानना पड़ता है।\n"
  "- **शपथपत्र:** पैसे और अपराधियों का प्रभाव कम करने के लिए **सर्वोच्च न्यायालय** ने एक आदेश (**2003**) दिया। अब चुनाव लड़ने वाले हर उम्मीदवार को अपनी **संपत्ति और अपने ख़िलाफ़ चल रहे आपराधिक मामलों** का ब्यौरा एक **शपथपत्र** के माध्यम से देना अनिवार्य है। यह जानकारी सार्वजनिक की जाती है। पर इस जानकारी के सही होने की जाँच की कोई व्यवस्था नहीं है।\n"
  "- **चुनाव आयोग का आदेश:** चुनाव आयोग ने आदेश दिया कि दलों को अपने **सांगठनिक चुनाव** कराने होंगे और **आयकर रिटर्न** भरना होगा। दलों ने ऐसा करना शुरू किया है, पर कभी-कभी यह सिर्फ़ औपचारिकता होती है।\n\n"
  "**आगे सुधार के सुझाव:**\n"
  "- दलों के **आंतरिक कामकाज को व्यवस्थित करने के लिए क़ानून**: सदस्यों की सूची रखना, अपने संविधान का पालन करना, दल के विवादों में फ़ैसले के लिए स्वतंत्र प्राधिकारी रखना, और सबसे बड़े पदों के लिए खुले चुनाव कराना।\n"
  "- दलों के लिए महिलाओं को एक ख़ास न्यूनतम अनुपात, लगभग **एक-तिहाई, टिकट** देना अनिवार्य करना; इसी तरह दल के प्रमुख पदों पर भी महिलाओं के लिए आरक्षण होना चाहिए।\n"
  "- **चुनाव का ख़र्च सरकार उठाए:** सरकार दलों को चुनाव ख़र्च के लिए पैसा दे, चीज़ों के रूप में (पेट्रोल, काग़ज़, फ़ोन आदि) या नक़द, पिछले चुनाव में मिले मतों के आधार पर।\n\n"
  "क़ानूनी सुधारों में सावधानी चाहिए: ज़रूरत से ज़्यादा क़ानूनी नियंत्रण उलटा असर कर सकता है, और दल क़ानून से बचने के रास्ते ढूँढ़ सकते हैं। दो और तरीक़े अहम हैं: **लोग दलों पर दबाव** डाल सकते हैं, याचिकाओं, प्रचार और आंदोलनों से, और मीडिया तथा आंदोलनों के ज़रिए; और **सुधार चाहने वाले लोग ख़ुद दलों में शामिल** हो सकते हैं, क्योंकि लोकतंत्र की गुणवत्ता जनता की भागीदारी पर निर्भर करती है।",
  "પક્ષો લોકશાહીનો સૌથી દેખીતો ચહેરો છે, તેથી લોકશાહીના કામકાજમાં જે કંઈ ખોટું છે તે માટે લોકો પક્ષોને દોષ આપે છે. લોકોનો અસંતોષ અને ટીકા **ચાર સમસ્યાઓ** પર કેન્દ્રિત રહી છે:\n\n"
  "1. **પક્ષમાં આંતરિક લોકશાહીનો અભાવ:** દુનિયાભરમાં પક્ષોમાં સત્તા **એક કે થોડા નેતાઓ** પાસે કેન્દ્રિત થવાનું વલણ છે. પક્ષો **સભ્યોનાં રજિસ્ટર** રાખતા નથી, **સંગઠનની બેઠકો** કરતા નથી, અને **આંતરિક ચૂંટણીઓ** નિયમિત કરાવતા નથી. સામાન્ય સભ્યોને પક્ષની અંદર શું થાય છે તેની પૂરતી માહિતી મળતી નથી અને નિર્ણયો પર પ્રભાવ પાડવાનાં સાધનો કે સંપર્કો હોતા નથી. નેતાઓ પક્ષના નામે નિર્ણયો લેવાની વધુ સત્તા લઈ લે છે. નેતૃત્વ સાથે અસંમત લોકો માટે પક્ષમાં ટકવું મુશ્કેલ બને છે. પક્ષના સિદ્ધાંતો અને નીતિઓ પ્રત્યેની વફાદારી કરતાં **નેતા પ્રત્યેની અંગત વફાદારી** વધુ મહત્ત્વની બને છે.\n"
  "2. **વંશવાદી ઉત્તરાધિકાર:** મોટા ભાગના પક્ષો ખુલ્લી અને પારદર્શક રીતે કામ કરતા નથી, તેથી સામાન્ય કાર્યકર માટે ટોચે પહોંચવાના બહુ ઓછા માર્ગ હોય છે. જે નેતાઓ હોય તેઓ અયોગ્ય લાભ લઈ પોતાના નજીકના લોકો કે પરિવારના સભ્યોની તરફેણ કરે છે. ઘણા પક્ષોમાં **ટોચના હોદ્દા હંમેશાં એક જ પરિવારના સભ્યો પાસે** રહે છે. આ પક્ષના બીજા સભ્યો સાથે અન્યાય છે અને લોકશાહી માટે ખરાબ છે, કારણ કે પૂરતા અનુભવ કે લોકપ્રિય ટેકા વિનાના લોકો સત્તાના હોદ્દા પર પહોંચે છે. આ વલણ કેટલીક જૂની લોકશાહી સહિત દુનિયાભરમાં અમુક અંશે છે.\n"
  "3. **નાણાં અને બાહુબળની વધતી ભૂમિકા:** પક્ષોનું ધ્યાન ફક્ત ચૂંટણી જીતવા પર હોય છે, તેથી તેઓ ટૂંકા રસ્તા અપનાવે છે. તેઓ એવા ઉમેદવારો ઊભા રાખે છે જેમની પાસે **ઘણા પૈસા** હોય કે જે પૈસા ભેગા કરી શકે. પક્ષોને ફંડ આપનારા ધનિકો અને કંપનીઓ તેમની નીતિઓ અને નિર્ણયો પર પ્રભાવ પાડે છે. કેટલાક કિસ્સામાં પક્ષો ચૂંટણી જીતી શકે તેવા **ગુનેગારો**ને ટેકો આપે છે. દુનિયાભરના લોકશાહીવાદીઓ લોકશાહી રાજકારણમાં ધનિકો અને મોટી કંપનીઓની વધતી ભૂમિકાથી ચિંતિત છે.\n"
  "4. **અર્થપૂર્ણ વિકલ્પનો અભાવ:** અર્થપૂર્ણ વિકલ્પ માટે પક્ષો નોંધપાત્ર રીતે જુદા હોવા જોઈએ. તાજેતરનાં વર્ષોમાં દુનિયાના મોટા ભાગના ભાગોમાં પક્ષો વચ્ચે **વૈચારિક તફાવત** ઘટ્યો છે. આપણા દેશમાં પણ મુખ્ય પક્ષો વચ્ચે આર્થિક મુદ્દાઓ પરનો તફાવત ઘટ્યો છે. ખરેખર જુદી નીતિઓ ઇચ્છતા લોકો પાસે કોઈ વિકલ્પ નથી. ક્યારેક લોકો ખૂબ જુદા નેતાઓ પણ ચૂંટી શકતા નથી, કારણ કે એ જ નેતાઓ એક પક્ષમાંથી બીજામાં જતા રહે છે.\n\n"
  "**પક્ષોમાં સુધારા માટે લેવાયેલાં પગલાં:**\n"
  "- **પક્ષાંતર વિરોધી કાયદો:** **પક્ષાંતર** એટલે જે પક્ષમાંથી ચૂંટાયા હોય તે છોડી બીજા પક્ષમાં જોડાવું. ઘણા ધારાસભ્યો અને સાંસદો પ્રધાન બનવા કે રોકડ લાભ માટે પક્ષાંતર કરતા હતા. બંધારણમાં સુધારો (**52મો સુધારો, 1985**) કરાયો જેથી કોઈ ધારાસભ્ય કે સાંસદ પક્ષ બદલે તો તે ધારાસભામાંની **બેઠક ગુમાવે**. તેનાથી પક્ષાંતર ઘટ્યું, પણ મતભેદ વ્યક્ત કરવો વધુ મુશ્કેલ બન્યો: સાંસદો અને ધારાસભ્યોએ પક્ષના નેતાઓ જે નક્કી કરે તે સ્વીકારવું પડે છે.\n"
  "- **સોગંદનામું:** નાણાં અને ગુનેગારોનો પ્રભાવ ઘટાડવા **સર્વોચ્ચ અદાલતે** આદેશ (**2003**) આપ્યો. હવે ચૂંટણી લડતા દરેક ઉમેદવારે પોતાની **મિલકત અને પોતાની સામે ચાલતા ફોજદારી કેસો**ની વિગતો આપતું **સોગંદનામું** રજૂ કરવું ફરજિયાત છે. આ માહિતી જાહેર કરાય છે. પણ માહિતી સાચી છે કે નહિ તે ચકાસવાની કોઈ વ્યવસ્થા નથી.\n"
  "- **ચૂંટણી પંચનો આદેશ:** ચૂંટણી પંચે આદેશ આપ્યો કે પક્ષોએ પોતાની **સંગઠનાત્મક ચૂંટણીઓ** કરાવવી અને **આવકવેરા રિટર્ન** ભરવું પડશે. પક્ષોએ તે શરૂ કર્યું છે, પણ ક્યારેક તે માત્ર ઔપચારિકતા હોય છે.\n\n"
  "**વધુ સુધારા માટેનાં સૂચનો:**\n"
  "- પક્ષોની **આંતરિક બાબતોનું નિયમન કરતો કાયદો**: સભ્યોનું રજિસ્ટર રાખવું, પોતાના બંધારણનું પાલન કરવું, પક્ષના વિવાદોમાં ન્યાયાધીશ તરીકે સ્વતંત્ર સત્તામંડળ રાખવું, અને સર્વોચ્ચ હોદ્દાઓ માટે ખુલ્લી ચૂંટણીઓ કરાવવી.\n"
  "- પક્ષો માટે સ્ત્રી ઉમેદવારોને ઓછામાં ઓછી, આશરે **એક-તૃતીયાંશ, ટિકિટ** આપવી ફરજિયાત બનાવવી; તે જ રીતે પક્ષનાં નિર્ણય લેતાં અંગોમાં પણ સ્ત્રીઓ માટે અનામત હોવી જોઈએ.\n"
  "- **ચૂંટણીઓનું સરકારી ભંડોળ:** સરકાર પક્ષોને ચૂંટણી ખર્ચ માટે પૈસા આપે, વસ્તુ રૂપે (પેટ્રોલ, કાગળ, ટેલિફોન વગેરે) કે રોકડમાં, ગઈ ચૂંટણીમાં મળેલા મતોના આધારે.\n\n"
  "કાનૂની સુધારામાં કાળજી જોઈએ: વધુ પડતું નિયમન ઊલટી અસર કરી શકે, અને પક્ષો કાયદામાંથી છટકવાના રસ્તા શોધી શકે. બીજા બે માર્ગ મહત્ત્વના છે: **લોકો પક્ષો પર દબાણ** લાવી શકે, અરજીઓ, પ્રચાર અને આંદોલનો દ્વારા, અને માધ્યમો તથા આંદોલનો દ્વારા; અને **સુધારા ઇચ્છતા લોકો પોતે પક્ષોમાં જોડાઈ** શકે, કારણ કે લોકશાહીની ગુણવત્તા જાહેર ભાગીદારી પર આધાર રાખે છે."),
 "s6.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s6.memory.body": (
  "- **कार्य \"चु-नी-क़ा-स-वि-ज-प\"**: चुनाव लड़ना, नीतियाँ, क़ानून, सरकार बनाना, विपक्ष, जनमत, पहुँच (योजनाओं तक)।\n- **हिस्से \"ने-स-अ\"**: नेता, सक्रिय सदस्य, अनुयायी।\n"
  "- **दलीय व्यवस्थाएँ: चीन = 1, अमेरिका/ब्रिटेन = 2, भारत = कई।**\n- **मान्यता: \"6% + 2 सीटें\" (राज्यस्तरीय); \"लोकसभा या 4 राज्यों में 6% + लोकसभा की 4 सीटें\" (राष्ट्रीय)।**\n"
  "- **राष्ट्रीय दल और वर्ष: \"INC 1885, CPI-M 1964, BJP 1980, BSP 1984, AAP 2012, NPP 2013\"।**\n- **चुनौतियाँ \"आं-वं-पै-वि\"**: आंतरिक लोकतंत्र, वंशवाद, पैसा और बाहुबल, विकल्प।\n"
  "- **उठाए गए क़दम: \"दल-बदल 1985, शपथपत्र 2003, चुनाव और आयकर (आयोग)\"।**",
  "- **કાર્યો \"ચૂં-ની-કા-સ-વિ-લો-પ\"**: ચૂંટણી લડવી, નીતિઓ, કાયદા, સરકાર રચવી, વિરોધપક્ષ, લોકમત, પહોંચ (યોજનાઓ સુધી).\n- **ઘટકો \"ને-સ-અ\"**: નેતાઓ, સક્રિય સભ્યો, અનુયાયીઓ.\n"
  "- **પક્ષ પ્રથાઓ: ચીન = 1, અમેરિકા/UK = 2, ભારત = અનેક.**\n- **માન્યતા: \"6% + 2 બેઠકો\" (રાજ્ય કક્ષા); \"લોકસભા કે 4 રાજ્યોમાં 6% + લોકસભાની 4 બેઠકો\" (રાષ્ટ્રીય).**\n"
  "- **રાષ્ટ્રીય પક્ષો અને વર્ષ: \"INC 1885, CPI-M 1964, BJP 1980, BSP 1984, AAP 2012, NPP 2013\".**\n- **પડકારો \"આં-વં-ના-વિ\"**: આંતરિક લોકશાહી, વંશવાદ, નાણાં અને બાહુબળ, વિકલ્પ.\n"
  "- **લેવાયેલાં પગલાં: \"પક્ષાંતર 1985, સોગંદનામું 2003, ચૂંટણી અને આવકવેરો (પંચ)\".**"),
 "s6.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s6.mistakes.body": (
  "1. यह कहना कि चीन में कोई दल नहीं: वहाँ **एकदलीय** व्यवस्था है (कम्युनिस्ट पार्टी)।\n2. यह कहना कि भारत में द्विदलीय व्यवस्था है: भारत में **बहुदलीय** व्यवस्था है।\n"
  "3. यह कहना कि भारत की दलीय व्यवस्था चुनाव आयोग तय करता है: दलीय व्यवस्था समाज, विभाजनों, इतिहास और चुनावों से **विकसित** होती है।\n"
  "4. मान्यता के नियम मिलाना: **राज्यस्तरीय** दल के लिए विधानसभा के 6% वोट और **2 सीटें**; **राष्ट्रीय** दल के लिए लोकसभा या 4 राज्यों में 6% और **लोकसभा की 4 सीटें**।\n"
  "5. यह कहना कि दल-बदल क़ानून से असहमति बढ़ी: इससे दल-बदल घटा पर **असहमति ज़ाहिर करना कठिन** हुआ।\n6. लिखना कि शपथपत्र का आदेश संसद ने दिया: यह **सर्वोच्च न्यायालय** का आदेश था।",
  "1. કહેવું કે ચીનમાં કોઈ પક્ષ નથી: ત્યાં **એકપક્ષ** પ્રથા છે (સામ્યવાદી પક્ષ).\n2. કહેવું કે ભારતમાં દ્વિપક્ષ પ્રથા છે: ભારતમાં **બહુપક્ષ** પ્રથા છે.\n"
  "3. કહેવું કે ભારતની પક્ષ પ્રથા ચૂંટણી પંચ નક્કી કરે છે: પક્ષ પ્રથા સમાજ, વિભાજનો, ઇતિહાસ અને ચૂંટણીઓથી **વિકસે** છે.\n"
  "4. માન્યતાના નિયમો ભેળવવા: **રાજ્ય કક્ષા**ના પક્ષ માટે વિધાનસભાના 6% મત અને **2 બેઠકો**; **રાષ્ટ્રીય** પક્ષ માટે લોકસભા કે 4 રાજ્યોમાં 6% અને **લોકસભાની 4 બેઠકો**.\n"
  "5. કહેવું કે પક્ષાંતર વિરોધી કાયદાથી મતભેદ વધ્યો: તેનાથી પક્ષાંતર ઘટ્યું પણ **મતભેદ વ્યક્ત કરવો મુશ્કેલ** બન્યો.\n6. લખવું કે સોગંદનામાનો આદેશ સંસદે આપ્યો: તે **સર્વોચ્ચ અદાલત**નો આદેશ હતો."),
 "s6.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s6.tip.body": (
  "राष्ट्रीय दलों और अपने राज्य के दो राज्यस्तरीय दलों के चुनाव चिह्न इकट्ठा कीजिए। समूहों से दल का स्थापना वर्ष, मुख्य विचार और यह राष्ट्रीय है या राज्यस्तरीय, पता करवाइए और एक मिनट का 'दल परिचय' प्रस्तुत करवाइए।",
  "રાષ્ટ્રીય પક્ષો અને તમારા રાજ્યના બે રાજ્ય કક્ષાના પક્ષોનાં ચૂંટણી પ્રતીકો ભેગાં કરો. જૂથોને પક્ષનું સ્થાપના વર્ષ, મુખ્ય વિચારો અને તે રાષ્ટ્રીય છે કે રાજ્ય કક્ષાનો, તે શોધવા કહો અને એક મિનિટનો 'પક્ષ પરિચય' રજૂ કરાવો."),
 "s6.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s6.reflection.body": (
  "अगर आप किसी राजनीतिक दल में शामिल होते, तो इस अध्याय की किस एक चुनौती को सबसे पहले ठीक करना चाहते, और कैसे?",
  "જો તમે કોઈ રાજકીય પક્ષમાં જોડાઓ, તો આ પ્રકરણના કયા એક પડકારને સૌથી પહેલાં સુધારવા માગો, અને કેવી રીતે?"),
 "s6.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s6.connection.body": (
  "- **अध्याय 1 (सत्ता की साझेदारी):** दलों और गठबंधनों में सत्ता की साझेदारी।\n- **अध्याय 2 (संघवाद):** 1990 के बाद क्षेत्रीय दल और गठबंधन सरकारें।\n- **अध्याय 5 (लोकतंत्र के परिणाम):** जवाबदेह और जनता की बात सुनने वाली सरकार।",
  "- **પ્રકરણ 1 (સત્તાની ભાગીદારી):** પક્ષો અને ગઠબંધનોમાં સત્તાની ભાગીદારી.\n- **પ્રકરણ 2 (સમવાયતંત્ર):** 1990 પછી પ્રાદેશિક પક્ષો અને ગઠબંધન સરકારો.\n- **પ્રકરણ 5 (લોકશાહીનાં પરિણામો):** જવાબદાર અને લોકોની વાત સાંભળતી સરકાર."),
 "s6.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s6.mastery.body": (
  "'आंतरिक लोकतंत्र का अभाव और वंशवाद राजनीतिक दलों की बड़ी चुनौतियाँ हैं।' लगभग 120 शब्दों में समझाइए।\n\n"
  "**आदर्श उत्तर:** राजनीतिक दलों में सत्ता शीर्ष के एक या कुछ नेताओं के हाथ में सिमट जाती है। वे सदस्यों की सूची नहीं रखते, सांगठनिक बैठकें नहीं करते और नियमित आंतरिक चुनाव नहीं कराते, इसलिए आम सदस्यों के पास कम जानकारी और कम प्रभाव होता है, और असहमत लोगों का टिकना मुश्किल होता है। "
  "दल के सिद्धांतों से ज़्यादा नेता के प्रति निजी निष्ठा अहम हो जाती है। दलों में खुली और पारदर्शी प्रक्रिया न होने से आम कार्यकर्ता के शीर्ष तक पहुँचने के बहुत कम रास्ते हैं। "
  "नेता अपने नज़दीकी लोगों या परिवार के सदस्यों को आगे बढ़ाते हैं, और कई दलों में शीर्ष पद हमेशा एक ही परिवार के पास रहते हैं। यह दूसरे सदस्यों के साथ अन्याय और लोकतंत्र के लिए बुरा है, क्योंकि पर्याप्त अनुभव या लोकप्रिय समर्थन के बिना लोग ताक़त वाले पदों पर पहुँच जाते हैं।",
  "'આંતરિક લોકશાહીનો અભાવ અને વંશવાદી ઉત્તરાધિકાર રાજકીય પક્ષો સામેના મોટા પડકારો છે.' આશરે 120 શબ્દોમાં સમજાવો.\n\n"
  "**આદર્શ જવાબ:** રાજકીય પક્ષોમાં સત્તા ટોચના એક કે થોડા નેતાઓ પાસે કેન્દ્રિત થાય છે. તેઓ સભ્યોનાં રજિસ્ટર રાખતા નથી, સંગઠનની બેઠકો કરતા નથી કે નિયમિત આંતરિક ચૂંટણીઓ કરાવતા નથી, તેથી સામાન્ય સભ્યો પાસે ઓછી માહિતી અને ઓછો પ્રભાવ હોય છે, અને અસંમત લોકો માટે ટકવું મુશ્કેલ બને છે. "
  "પક્ષના સિદ્ધાંતો કરતાં નેતા પ્રત્યેની અંગત વફાદારી વધુ મહત્ત્વની બને છે. પક્ષોમાં ખુલ્લી અને પારદર્શક પ્રક્રિયા ન હોવાથી સામાન્ય કાર્યકર માટે ટોચે પહોંચવાના બહુ ઓછા માર્ગ છે. "
  "નેતાઓ પોતાના નજીકના લોકો કે પરિવારના સભ્યોની તરફેણ કરે છે, અને ઘણા પક્ષોમાં ટોચના હોદ્દા હંમેશાં એક જ પરિવાર પાસે રહે છે. આ બીજા સભ્યો સાથે અન્યાય અને લોકશાહી માટે ખરાબ છે, કારણ કે પૂરતા અનુભવ કે લોકપ્રિય ટેકા વિનાના લોકો સત્તાના હોદ્દા પર પહોંચે છે."),
 "s6.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s6.summary.body": (
  "- राजनीतिक दल चुनाव लड़ने और सत्ता पाने के लिए एकजुट लोगों का समूह है; इसके हिस्से हैं नेता, सक्रिय सदस्य और अनुयायी।\n"
  "- दल चुनाव लड़ते हैं, नीतियाँ रखते हैं, क़ानून बनाते हैं, सरकार बनाते हैं, विपक्ष की भूमिका निभाते हैं, जनमत बनाते हैं और सरकारी योजनाओं तक पहुँच देते हैं।\n"
  "- दलीय व्यवस्थाएँ: एकदलीय (चीन), द्विदलीय (अमेरिका, ब्रिटेन), बहुदलीय (भारत); दलीय व्यवस्था विकसित होती है, चुनी नहीं जाती।\n"
  "- चुनाव आयोग राज्यस्तरीय और राष्ट्रीय दलों को मान्यता देता है (6% वोट और सीटें) और उन्हें अलग चिह्न देता है।\n"
  "- चुनौतियाँ: आंतरिक लोकतंत्र का अभाव, वंशवाद, पैसे और बाहुबल की भूमिका, सार्थक विकल्प का अभाव।\n"
  "- सुधार: दल-बदल विरोधी क़ानून, संपत्ति और आपराधिक मामलों का शपथपत्र, सांगठनिक चुनाव और आयकर रिटर्न; सुझाव: आंतरिक कामकाज का नियमन, महिलाओं को टिकट और चुनाव का सरकारी ख़र्च।",
  "- રાજકીય પક્ષ ચૂંટણી લડવા અને સત્તા મેળવવા ભેગા થયેલા લોકોનું જૂથ છે; તેના ઘટકો છે નેતાઓ, સક્રિય સભ્યો અને અનુયાયીઓ.\n"
  "- પક્ષો ચૂંટણી લડે છે, નીતિઓ રજૂ કરે છે, કાયદા ઘડે છે, સરકાર રચે છે, વિરોધપક્ષની ભૂમિકા ભજવે છે, લોકમત ઘડે છે અને સરકારી યોજનાઓ સુધી પહોંચ આપે છે.\n"
  "- પક્ષ પ્રથાઓ: એકપક્ષ (ચીન), દ્વિપક્ષ (અમેરિકા, UK), બહુપક્ષ (ભારત); પક્ષ પ્રથા વિકસે છે, પસંદ કરાતી નથી.\n"
  "- ચૂંટણી પંચ રાજ્ય કક્ષાના અને રાષ્ટ્રીય પક્ષોને માન્યતા આપે છે (6% મત અને બેઠકો) અને તેમને અલગ પ્રતીક આપે છે.\n"
  "- પડકારો: આંતરિક લોકશાહીનો અભાવ, વંશવાદ, નાણાં અને બાહુબળની ભૂમિકા, અર્થપૂર્ણ વિકલ્પનો અભાવ.\n"
  "- સુધારા: પક્ષાંતર વિરોધી કાયદો, મિલકત અને ફોજદારી કેસોનું સોગંદનામું, સંગઠનાત્મક ચૂંટણીઓ અને આવકવેરા રિટર્ન; સૂચનો: આંતરિક બાબતોનું નિયમન, સ્ત્રીઓને ટિકિટ અને ચૂંટણીઓનું સરકારી ભંડોળ."),
 "s6.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s6.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में विकल्प सहित 5 अंक का प्रश्न था: लोकतंत्र में दलों की अहम भूमिका समझाइए (कार्य), या विश्लेषण कीजिए कि नेतृत्व का उत्तराधिकार भारत में दलों के लिए चुनौती कैसे है (वंशवाद)।\n"
  "- 3/5 अंक के पसंदीदा प्रश्न: कार्य, दलों की ज़रूरत, दलीय व्यवस्थाएँ, राष्ट्रीय दलों का परिचय, चुनौतियाँ और सुधार।\n"
  "- 5 अंक के उत्तर में हर बिंदु के शीर्षक के साथ पाँच अलग बिंदु लिखें।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં વિકલ્પ સાથેનો 5 ગુણનો પ્રશ્ન હતો: લોકશાહીમાં પક્ષોની મહત્ત્વની ભૂમિકા સમજાવો (કાર્યો), કે વિશ્લેષણ કરો કે નેતૃત્વનો ઉત્તરાધિકાર ભારતમાં પક્ષો માટે પડકાર કેવી રીતે છે (વંશવાદ).\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: કાર્યો, પક્ષોની આવશ્યકતા, પક્ષ પ્રથાઓ, રાષ્ટ્રીય પક્ષોનો પરિચય, પડકારો અને સુધારા.\n"
  "- 5 ગુણના જવાબમાં દરેક મુદ્દાના શીર્ષક સાથે પાંચ અલગ મુદ્દા લખો."),
 "s6.flash1.front": ("राजनीतिक दल क्या है?", "રાજકીય પક્ષ શું છે?"),
 "s6.flash1.back": ("लोगों का समूह जो चुनाव लड़ने और सरकार में सत्ता पाने के लिए एकजुट होता है, और सामूहिक हित के लिए नीतियों पर सहमत होता है।", "લોકોનું જૂથ જે ચૂંટણી લડવા અને સરકારમાં સત્તા મેળવવા ભેગું થાય છે, અને સામૂહિક હિત માટે નીતિઓ પર સંમત થાય છે."),
 "s6.flash2.front": ("दल-बदल क्या है?", "પક્ષાંતર શું છે?"),
 "s6.flash2.back": ("जिस दल से चुने गए उसे छोड़कर दूसरे दल में चले जाना।", "જે પક્ષમાંથી ચૂંટાયા હોય તે છોડી બીજા પક્ષમાં જોડાવું."),
 "s6.flash3.front": ("गठबंधन या मोर्चा क्या है?", "ગઠબંધન કે મોરચો શું છે?"),
 "s6.flash3.back": ("जब बहुदलीय व्यवस्था में कई दल चुनाव लड़ने और सत्ता पाने के लिए हाथ मिलाते हैं, जैसे एनडीए और यूपीए।", "જ્યારે બહુપક્ષ પ્રથામાં અનેક પક્ષો ચૂંટણી લડવા અને સત્તા મેળવવા હાથ મિલાવે, જેમ કે NDA અને UPA."),
 "s6.flash4.front": ("राजनीतिक दलों की चार चुनौतियाँ बताइए।", "રાજકીય પક્ષો સામેના ચાર પડકારો જણાવો."),
 "s6.flash4.back": ("आंतरिक लोकतंत्र का अभाव; वंशवाद; पैसे और बाहुबल की बढ़ती भूमिका; सार्थक विकल्प का अभाव।", "આંતરિક લોકશાહીનો અભાવ; વંશવાદી ઉત્તરાધિકાર; નાણાં અને બાહુબળની વધતી ભૂમિકા; અર્થપૂર્ણ વિકલ્પનો અભાવ."),
}
